get_ipython().run_cell_magic('writefile', f'{STAGING}/e4_masks.py', '"""Frozen E4 source partitions and orthographic tokenization covariates."""\nimport unicodedata\nimport numpy as np\nfrom e1_core import require\n\nFINE_COMPONENTS=[\'source_tag\',\'target_tag\',\'source_code\',\'eos\',\'unknown\',\'blank\',\'punctuation_P\',\'symbol_control\',\'content\']\nOUTCOMES=[\'raw_lm\',\'raw_P_only\',\'lexical_no_unknown\',\'conditional_original\',\'conditional_no_separator\',\n          \'conditional_P_only_no_separator\',\'conditional_no_separator_no_unknown\']\n\ndef cleaned(piece):return str(piece).replace(\'▁\',\'\').replace(\'Ġ\',\'\').strip()\n\ndef finer_positions(base,ids,pieces,unk_id):\n    fine={k:[] for k in FINE_COMPONENTS}\n    for k in [\'source_tag\',\'target_tag\',\'source_code\',\'eos\']:fine[k]=list(base.get(k,[]))\n    body=sorted(set(base[\'lexical\']+base[\'punctuation\']+base.get(\'unknown\',[])))\n    for i in body:\n        if ids[i]==unk_id:fine[\'unknown\'].append(i)\n        elif i in base[\'lexical\']:fine[\'content\'].append(i)\n        else:\n            s=cleaned(pieces[i])\n            if not s:fine[\'blank\'].append(i)\n            elif all(unicodedata.category(ch)[0]==\'P\' for ch in s):fine[\'punctuation_P\'].append(i)\n            else:fine[\'symbol_control\'].append(i)\n    require(sorted(sum(fine.values(),[]))==sorted(sum(base.values(),[])),\'Fine mask does not partition the original support\')\n    require(len(sum(fine.values(),[]))==len(set(sum(fine.values(),[]))),\'Overlapping source components\')\n    return fine\n\ndef word_estimate(text):\n    # Same raw meaning/language text across models. This is an orthographic\n    # whitespace estimate, not a validated linguistic word segmentation.\n    return sum(any(unicodedata.category(ch)[0] in {\'L\',\'M\',\'N\'} for ch in word) for word in str(text).split())\n\ndef boundary_words(pieces,lexical_indices):\n    # Carry standalone SentencePiece boundaries to the following lexical token.\n    # Filtering blank pieces before counting would lose these word boundaries.\n    wanted=set(lexical_indices);pending=True;count=0\n    for i,piece in enumerate(pieces):\n        piece=str(piece)\n        if piece.startswith((\'▁\',\'Ġ\')):pending=True\n        if i in wanted:\n            if pending:count+=1\n            pending=False\n    return count\n\ndef outcomes_from_means(means,unknown_retained):\n    content=float(means[\'content\']);unk=float(means[\'unknown\'])\n    lexical=content+(unk if unknown_retained else 0.0)\n    p=float(means[\'punctuation_P\']);s=float(means[\'symbol_control\']);blank=float(means[\'blank\'])\n    require(lexical>0 and content>0,\'No lexical mass; conditional shares are undefined\')\n    return {\'raw_lm\':lexical,\'raw_P_only\':lexical+s,\'lexical_no_unknown\':content,\n        \'conditional_original\':lexical/(lexical+p+s+blank),\n        \'conditional_no_separator\':lexical/(lexical+p+s),\n        \'conditional_P_only_no_separator\':(lexical+s)/(lexical+p+s),\n        \'conditional_no_separator_no_unknown\':content/(content+p+s)}\n\ndef covariates(record,base,fine,pieces,source_ids):\n    words=word_estimate(record[\'src_text\']);require(words>0,\'No orthographic source words\')\n    lexical=len(base[\'lexical\']);body=sum(len(fine[k]) for k in [\'unknown\',\'blank\',\'punctuation_P\',\'symbol_control\',\'content\'])\n    require(lexical>0 and body>0,\'No source lexical/body tokens\')\n    return {\'source_lexical_pieces\':lexical,\'source_content_pieces\':len(fine[\'content\']),\n        \'source_word_estimate\':words,\'source_boundary_word_estimate\':boundary_words(pieces,base[\'lexical\']),\n        \'source_fertility\':lexical/words,\'source_content_fertility\':len(fine[\'content\'])/words,\n        \'source_punctuation_P_count\':len(fine[\'punctuation_P\']),\'source_symbol_control_count\':len(fine[\'symbol_control\']),\n        \'source_blank_count\':len(fine[\'blank\']),\'source_unknown_count\':len(fine[\'unknown\']),\n        \'source_punctuation_fraction\':(len(fine[\'punctuation_P\'])+len(fine[\'symbol_control\']))/body,\n        \'source_unknown_fraction\':len(fine[\'unknown\'])/body,\'source_blank_fraction\':len(fine[\'blank\'])/body,\n        \'source_total_tokens\':len(source_ids)}\n\ndef aggregate_attention(attention_layers,fine,target_rows):\n    """Works on CPU/GPU tensors, preserving the collector\'s row/head averaging."""\n    import torch\n    shares=[];closure=0.0\n    for attention in attention_layers:\n        require(attention.dtype==torch.float32,\'E4 attention is not fp32\')\n        a=attention[0].index_select(1,torch.tensor(target_rows,device=attention.device))\n        require(bool(torch.isfinite(a).all()) and float(a.min())>=-1e-7,\'Invalid attention\')\n        closure=max(closure,float((a.sum(-1)-1).abs().max()))\n        h=torch.stack([a[:,:,fine[k]].sum(-1).mean(-1) for k in FINE_COMPONENTS],-1)\n        shares.append(h.cpu().numpy())\n    array=np.stack(shares).astype(np.float32)\n    require(closure<1e-5 and np.max(np.abs(array.sum(-1)-1))<1e-5,\'Per-head/target-row closure failed\')\n    return array,closure\n\ndef prefix_separator_mass(attention_layers,fine,target_rows):\n    """Diagnostic subset of blank: separators before the first language tag/code."""\n    import torch\n    language_positions=sum((fine[k] for k in [\'source_tag\',\'target_tag\',\'source_code\']),[])\n    if not language_positions:return 0.0\n    prefix=[i for i in fine[\'blank\'] if i<min(language_positions)]\n    if not prefix:return 0.0\n    values=[]\n    for attention in attention_layers:\n        a=attention[0].index_select(1,torch.tensor(target_rows,device=attention.device))\n        values.append(a[:,:,prefix].sum(-1).mean())\n    return float(torch.stack(values).mean())\n')


