# Bounded live output; full worker logs are preserved separately.
from collections import deque
from html import escape
from IPython.display import HTML,clear_output
import shutil

def run_live(command,environment=None,log_name='worker.log'):
    process=subprocess.Popen(command,env=environment,stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,text=True,bufsize=1,errors='replace')
    lines=queue.Queue();tail=deque(maxlen=20)
    display(HTML('<pre>Starting…</pre>'))
    started=time.monotonic();last_update=0.0;last_heartbeat=started
    log_path=STAGING/log_name
    def reader():
        try:
            for line in process.stdout:lines.put(line)
        finally:lines.put(None)
    def refresh():
        text='\n'.join(tail)[-8000:]
        clear_output(wait=True)
        display(HTML('<pre style="max-height:340px;overflow:auto">'+escape(text)+'</pre>'))
    threading.Thread(target=reader,daemon=True).start()
    try:
        with log_path.open('a',encoding='utf-8') as log:
            while True:
                try:
                    line=lines.get(timeout=1)
                    if line is None:break
                    log.write(line);log.flush();tail.append(line.rstrip()[-2000:])
                except queue.Empty:pass
                now=time.monotonic()
                if now-last_heartbeat>=30:
                    message=f'Process alive for {(now-started)/60:.1f} min; waiting for next stage output.'
                    tail.append(message);log.write(message+'\n');last_heartbeat=now
                if now-last_update>=2:refresh();last_update=now
        returncode=process.wait()
        if returncode:raise subprocess.CalledProcessError(returncode,command)
    except BaseException:
        if process.poll() is None:
            process.terminate()
            try:process.wait(timeout=10)
            except subprocess.TimeoutExpired:process.kill();process.wait()
        raise
    finally:
        refresh()
        destination=OUTPUT_ROOT/'private_logs';destination.mkdir(parents=True,exist_ok=True)
        if log_path.is_file():shutil.copyfile(log_path,destination/log_path.name)
        print('Full log:',destination/log_path.name)

def completed(study):
    root=OUTPUT_ROOT/'collectors'/study;p=root/'complete.json'
    if not p.is_file():return False
    stamp=json.loads(p.read_text())
    require(stamp['worker_sha256']==SOURCE_HASHES['e4_worker.py'] and stamp['support_code_sha256']==SOURCE_HASHES,'Completed E4 code differs')
    require(stamp['baseline_sha256']==sha256_file(BASELINE_PATHS[study]),'Completed E4 original baseline differs')
    require(stamp['all_rows_sha256']==sha256_file(root/'all_rows.csv'),'Completed E4 rows changed')
    require(stamp['run_lock_sha256']==sha256_file(root/'run_lock.json'),'Completed E4 lock changed')
    require(stamp['token_ids_sha256']==sha256_file(root/'private_tokenization/input_ids.csv'),'Frozen token IDs changed')
    return True


