def pinned_checkout(name,url,revision):
    path=DEPENDENCIES/name
    if not (path/'.git').is_dir():
        path.mkdir(parents=True,exist_ok=True)
        run_live(['git','init',str(path)],log_name='setup.log')
        run_live(['git','-C',str(path),'remote','add','origin',url],log_name='setup.log')
    result=subprocess.run(['git','-C',str(path),'rev-parse','HEAD'],capture_output=True,text=True)
    if result.returncode!=0:
        run_live(['git','-C',str(path),'fetch','--depth','1','origin',revision],log_name='setup.log')
        run_live(['git','-C',str(path),'checkout','--detach',revision],log_name='setup.log')
    actual=subprocess.check_output(['git','-C',str(path),'rev-parse','HEAD'],text=True).strip()
    require(actual==revision,'Pinned normalization checkout differs: '+name)
    return path
